<script setup lang="ts">import type{BatchRecord}from'../../types/batches';defineProps<{batches:BatchRecord[]}>();defineEmits<{open:[id:string]}>();const labels={DRAFT:'草稿',UPLOADING:'上传中',PROCESSING:'处理中',PARTIAL_FAILED:'部分失败',COMPLETED:'已完成',CANCELLED:'已取消'} as const</script>
<template><section class="library-panel batch-list"><div class="section-heading"><div><p class="eyebrow">IMPORT HISTORY</p><h2>导入批次 <span>{{batches.length}}</span></h2></div></div><div v-if="batches.length" class="batch-cards"><button v-for="batch in batches" :key="batch.id" @click="$emit('open',batch.id)"><span><b>{{batch.name}}</b><small>{{new Date(batch.created_at).toLocaleString()}} · {{labels[batch.status]}}</small></span><span class="batch-counts"><b>{{batch.indexed_count}} / {{batch.total_count}}</b><small>可检索 / 总数</small></span><span v-if="batch.failed_count" class="batch-failed">{{batch.failed_count}} 个失败</span></button></div><p v-else class="empty">还没有批量导入记录。</p></section></template>
